-- Aprenda se Divertindo · 85 · Trilha Saúde · lote extra 9 (500 questões, de fácil a desafio)
-- Rode depois do 84-trilha-tribunais-extra-2.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Cálculos de medicação (gotejamento, diluição, dose por peso, penicilina, heparina, insulina) feitos por programa.
-- Conteúdo baseado em leis e protocolos consolidados (Lei 7.498, Lei 8.080, Lei 8.142, Cofen, Ministério da Saúde).
-- Conferidas contra o banco para não repetir.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":8947,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 500 mL de soro em 8 horas. Quantas gotas por minuto (macrogotas)?","opcoes":["Cerca de 21 gotas/min","62 gotas/min","188 gotas/min","42 gotas/min"],"explicacao":"Gotas/min = V ÷ (T × 3) = 500 ÷ (8 × 3) = 20,8."},{"id":8948,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 1000 mL de soro em 12 horas. Quantas gotas por minuto (macrogotas)?","opcoes":["Cerca de 28 gotas/min","83 gotas/min","250 gotas/min","56 gotas/min"],"explicacao":"Gotas/min = V ÷ (T × 3) = 1000 ÷ (12 × 3) = 27,8."},{"id":8949,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 1000 mL de soro em 24 horas. Quantas gotas por minuto (macrogotas)?","opcoes":["Cerca de 14 gotas/min","42 gotas/min","125 gotas/min","28 gotas/min"],"explicacao":"Gotas/min = V ÷ (T × 3) = 1000 ÷ (24 × 3) = 13,9."},{"id":8950,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 480 mL em 8 horas. Quantas microgotas por minuto?","opcoes":["60 microgotas/min","20 microgotas/min","180 microgotas/min","30 microgotas/min"],"explicacao":"Microgotas/min = V ÷ T = 480 ÷ 8 = 60."},{"id":8951,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 300 mL em 6 horas. Quantas microgotas por minuto?","opcoes":["50 microgotas/min","17 microgotas/min","150 microgotas/min","25 microgotas/min"],"explicacao":"Microgotas/min = V ÷ T = 300 ÷ 6 = 50."},{"id":8952,"materia":"enf","nivel":2,"enunciado":"Devem ser infundidos 720 mL em 24 horas. Quantas microgotas por minuto?","opcoes":["30 microgotas/min","10 microgotas/min","90 microgotas/min","15 microgotas/min"],"explicacao":"Microgotas/min = V ÷ T = 720 ÷ 24 = 30."},{"id":8953,"materia":"enf","nivel":1,"enunciado":"Uma bomba de infusão deve infundir 500 mL em 5 horas. A vazão programada é:","opcoes":["100 mL/h","33,3 mL/h","2.500 mL/h","1,7 mL/h"],"explicacao":"Vazão (mL/h) = volume ÷ tempo em horas."},{"id":8954,"materia":"enf","nivel":1,"enunciado":"Uma bomba de infusão deve infundir 1000 mL em 8 horas. A vazão programada é:","opcoes":["125 mL/h","41,7 mL/h","8.000 mL/h","2,1 mL/h"],"explicacao":"Vazão (mL/h) = volume ÷ tempo em horas."},{"id":8955,"materia":"enf","nivel":3,"enunciado":"Um soro está correndo a 20 gotas por minuto. Quantos mL são infundidos em 1 hora?","opcoes":["60 mL","1.200 mL","120 mL","30 mL"],"explicacao":"1 mL = 20 gotas: 20 gotas/min = 1 mL/min × 60 min."},{"id":8956,"materia":"enf","nivel":3,"enunciado":"Um soro está correndo a 40 gotas por minuto. Quantos mL são infundidos em 1 hora?","opcoes":["120 mL","2.400 mL","240 mL","60 mL"],"explicacao":"1 mL = 20 gotas: 40 gotas/min = 2 mL/min × 60 min."},{"id":8957,"materia":"enf","nivel":1,"enunciado":"Prescrição: 200 mg. Disponível: ampola de 500 mg em 5 mL. Quantos mL aspirar?","opcoes":["2 mL","12,5 mL","0,4 mL","4 mL"],"explicacao":"Regra de três: 500 mg — 5 mL; 200 mg — x."},{"id":8958,"materia":"enf","nivel":1,"enunciado":"Prescrição: 60 mg. Disponível: ampola de 80 mg em 2 mL. Quantos mL aspirar?","opcoes":["1,5 mL","2,67 mL","0,75 mL","3 mL"],"explicacao":"Regra de três: 80 mg — 2 mL; 60 mg — x."},{"id":8959,"materia":"enf","nivel":1,"enunciado":"Prescrição: 750 mg. Disponível: ampola de 1000 mg em 10 mL. Quantos mL aspirar?","opcoes":["7,5 mL","13,33 mL","0,75 mL","15 mL"],"explicacao":"Regra de três: 1000 mg — 10 mL; 750 mg — x."},{"id":8960,"materia":"enf","nivel":1,"enunciado":"Prescrição: 150 mg. Disponível: ampola de 250 mg em 5 mL. Quantos mL aspirar?","opcoes":["3 mL","8,33 mL","0,6 mL","6 mL"],"explicacao":"Regra de três: 250 mg — 5 mL; 150 mg — x."},{"id":8961,"materia":"enf","nivel":3,"enunciado":"Prescrição: 2.500 UI de heparina. Frasco com 5.000 UI em 1 mL. Quantos mL aspirar?","opcoes":["0,5 mL","2 mL","5 mL","0,25 mL"],"explicacao":"Regra de três entre unidades e volume."},{"id":8962,"materia":"enf","nivel":3,"enunciado":"Prescrição: 1.000 UI de heparina. Frasco com 5.000 UI em 5 mL. Quantos mL aspirar?","opcoes":["1 mL","25 mL","10 mL","0,5 mL"],"explicacao":"Regra de três entre unidades e volume."},{"id":8963,"materia":"enf","nivel":2,"enunciado":"Na seringa de insulina de 100 UI/mL, 10 UI correspondem a quantos mL?","opcoes":["0,1 mL","10 mL","1 mL","0,01 mL"],"explicacao":"100 UI = 1 mL."},{"id":8964,"materia":"enf","nivel":2,"enunciado":"Na seringa de insulina de 100 UI/mL, 24 UI correspondem a quantos mL?","opcoes":["0,24 mL","24 mL","2,4 mL","0,024 mL"],"explicacao":"100 UI = 1 mL."},{"id":8965,"materia":"enf","nivel":2,"enunciado":"Na seringa de insulina de 100 UI/mL, 36 UI correspondem a quantos mL?","opcoes":["0,36 mL","36 mL","3,6 mL","0,036 mL"],"explicacao":"100 UI = 1 mL."},{"id":8966,"materia":"enf","nivel":2,"enunciado":"Quantos gramas de glicose há em 20 mL de soro glicosado a 50%?","opcoes":["10 g","1.000 g","100 g","5 g"],"explicacao":"50% = 50 g em 100 mL."},{"id":8967,"materia":"enf","nivel":3,"enunciado":"Quantos gramas de cloreto de sódio há em 500 mL de soro fisiológico a 0,9%?","opcoes":["4,5 g","45 g","0,5 g","9 g"],"explicacao":"0,9% = 0,9 g em 100 mL."},{"id":8968,"materia":"enf","nivel":3,"enunciado":"Quantos gramas de cloreto de sódio há em 1000 mL de soro fisiológico a 0,9%?","opcoes":["9 g","90 g","0,9 g","18 g"],"explicacao":"0,9% = 0,9 g em 100 mL."},{"id":8969,"materia":"enf","nivel":4,"enunciado":"Penicilina cristalina: frasco de 5.000.000 UI diluído em 8 mL de água destilada (o pó acrescenta 2 mL). Para 1.000.000 UI, aspira-se:","opcoes":["2 mL","1,6 mL","4 mL","3 mL"],"explicacao":"Volume final = 8 + 2 = 10 mL. Regra de três com 10 mL."},{"id":8970,"materia":"enf","nivel":4,"enunciado":"Penicilina cristalina: frasco de 5.000.000 UI diluído em 8 mL de água destilada (o pó acrescenta 2 mL). Para 2.500.000 UI, aspira-se:","opcoes":["5 mL","4 mL","10 mL","6 mL"],"explicacao":"Volume final = 8 + 2 = 10 mL. Regra de três com 10 mL."},{"id":8971,"materia":"enf","nivel":4,"enunciado":"Uma criança de 20 kg deve receber 10 mg/kg de um medicamento. A apresentação é 100 mg/1 mL. Quantos mL administrar?","opcoes":["2 mL","0,1 mL","4 mL","200 mL"],"explicacao":"Dose = 10 × 20 = 200 mg; 100 mg — 1 mL."},{"id":8972,"materia":"enf","nivel":4,"enunciado":"Uma criança de 12 kg deve receber 15 mg/kg de um medicamento. A apresentação é 200 mg/5 mL. Quantos mL administrar?","opcoes":["4,5 mL","0,38 mL","9 mL","180 mL"],"explicacao":"Dose = 15 × 12 = 180 mg; 200 mg — 5 mL."},{"id":8973,"materia":"enf","nivel":4,"enunciado":"Uma criança de 30 kg deve receber 5 mg/kg de um medicamento. A apresentação é 50 mg/1 mL. Quantos mL administrar?","opcoes":["3 mL","0,1 mL","6 mL","150 mL"],"explicacao":"Dose = 5 × 30 = 150 mg; 50 mg — 1 mL."},{"id":8974,"materia":"enf","nivel":3,"enunciado":"Um paciente recebeu 1.500 mL de soro e 600 mL de líquidos por via oral e eliminou 1.800 mL de urina em 24 h. O balanço hídrico (sem perdas insensíveis) é:","opcoes":["Positivo em 300 mL","Negativo em 300 mL","Positivo em 2.100 mL","Zero"],"explicacao":"Ganhos 2.100 − perdas 1.800."},{"id":8975,"materia":"enf","nivel":2,"enunciado":"Quantas gotas há em 2 mL de solução?","opcoes":["40 gotas","20 gotas","120 gotas","60 gotas"],"explicacao":"1 mL = 20 gotas."},{"id":8976,"materia":"enf","nivel":2,"enunciado":"Quantas microgotas há em 2 mL de solução?","opcoes":["120 microgotas","40 microgotas","60 microgotas","20 microgotas"],"explicacao":"1 mL = 60 microgotas."},{"id":8977,"materia":"enf","nivel":1,"enunciado":"Quantos mililitros equivalem a uma colher de sopa, pela convenção usada em enfermagem?","opcoes":["15 mL","5 mL","10 mL","2,5 mL"],"explicacao":"Colher de chá: 5 mL; sobremesa: 10 mL."},{"id":8978,"materia":"enf","nivel":0,"enunciado":"O órgão que fiscaliza o exercício profissional da enfermagem nos estados é o:","opcoes":["Coren","CRM","CRF","Crefito"],"explicacao":"Lei 5.905/1973."},{"id":8979,"materia":"enf","nivel":0,"enunciado":"Fazem parte da equipe de enfermagem, pela Lei 7.498/1986:","opcoes":["Enfermeiro, técnico de enfermagem, auxiliar de enfermagem e parteira","Médico e enfermeiro","Enfermeiro e farmacêutico","Apenas o enfermeiro"],"explicacao":"Lei 7.498/1986, art. 2º, parágrafo único."},{"id":8980,"materia":"enf","nivel":0,"enunciado":"Os técnicos e auxiliares de enfermagem atuam:","opcoes":["Sob orientação e supervisão do enfermeiro","De forma totalmente independente","Sob supervisão do farmacêutico","Sem nenhuma supervisão"],"explicacao":"Lei 7.498/1986, art. 15."},{"id":8981,"materia":"enf","nivel":0,"enunciado":"Os valores normais de frequência cardíaca em adultos em repouso são, em geral:","opcoes":["60 a 100 bpm","40 a 60 bpm","100 a 140 bpm","20 a 40 bpm"],"explicacao":""},{"id":8982,"materia":"enf","nivel":0,"enunciado":"A frequência cardíaca acima de 100 bpm no adulto em repouso é chamada de:","opcoes":["Taquicardia","Bradicardia","Taquipneia","Hipertermia"],"explicacao":""},{"id":8983,"materia":"enf","nivel":0,"enunciado":"A frequência respiratória abaixo do normal chama-se:","opcoes":["Bradipneia","Taquipneia","Apneia","Dispneia"],"explicacao":""},{"id":8984,"materia":"enf","nivel":0,"enunciado":"A ausência de respiração chama-se:","opcoes":["Apneia","Dispneia","Ortopneia","Bradipneia"],"explicacao":""},{"id":8985,"materia":"enf","nivel":0,"enunciado":"A respiração normal chama-se:","opcoes":["Eupneia","Dispneia","Apneia","Ortopneia"],"explicacao":""},{"id":8986,"materia":"enf","nivel":0,"enunciado":"A dor é considerada, na prática clínica, o:","opcoes":["Quinto sinal vital","Primeiro sinal vital","Sinal de morte","Sintoma sem importância"],"explicacao":""},{"id":8987,"materia":"enf","nivel":0,"enunciado":"Para medir a pressão arterial corretamente, o braço do paciente deve ficar:","opcoes":["Apoiado, na altura do coração","Pendurado ao lado do corpo","Acima da cabeça","Dobrado sobre o peito"],"explicacao":""},{"id":8988,"materia":"enf","nivel":0,"enunciado":"A higienização das mãos é considerada:","opcoes":["A medida mais simples e eficaz para prevenir infecções relacionadas à assistência","Opcion