ade","Hierarquização","Descentralização"],"explicacao":""},{"id":9156,"materia":"sus","nivel":0,"enunciado":"O princípio do SUS que significa tratar de forma desigual os desiguais, priorizando quem mais precisa, é a:","opcoes":["Equidade","Universalidade","Integralidade","Regionalização"],"explicacao":""},{"id":9157,"materia":"sus","nivel":0,"enunciado":"O princípio do SUS que garante ações de promoção, prevenção, tratamento e reabilitação é a:","opcoes":["Integralidade","Universalidade","Equidade","Descentralização"],"explicacao":""},{"id":9158,"materia":"sus","nivel":0,"enunciado":"A porta de entrada preferencial do SUS é a:","opcoes":["Atenção básica (atenção primária)","Emergência hospitalar","UTI","Clínica particular"],"explicacao":""},{"id":9159,"materia":"sus","nivel":0,"enunciado":"As instâncias colegiadas do SUS em cada esfera de governo são:","opcoes":["A Conferência de Saúde e o Conselho de Saúde","O Ministério e a Secretaria","A Câmara e o Senado","O hospital e o posto"],"explicacao":"Lei 8.142/1990, art. 1º."},{"id":9160,"materia":"sus","nivel":0,"enunciado":"A agência que coordena a vigilância sanitária no Brasil é a:","opcoes":["Anvisa","ANS","Funasa","Fiocruz"],"explicacao":""},{"id":9161,"materia":"sus","nivel":0,"enunciado":"A agência que regula os planos de saúde é a:","opcoes":["ANS","Anvisa","Inmetro","Procon"],"explicacao":""},{"id":9162,"materia":"sus","nivel":0,"enunciado":"O Disque Saúde do Ministério da Saúde é o número:","opcoes":["136","190","192","100"],"explicacao":""},{"id":9163,"materia":"sus","nivel":1,"enunciado":"Pela Constituição, a iniciativa privada pode participar do SUS:","opcoes":["De forma complementar, com preferência para entidades filantrópicas e sem fins lucrativos","Substituindo o serviço público","Proibida em qualquer caso","Só com hospitais estrangeiros"],"explicacao":"CF, art. 199, § 1º."},{"id":9164,"materia":"sus","nivel":1,"enunciado":"É permitida a comercialização de sangue e órgãos no Brasil?","opcoes":["Não","S