ica","Excêntrica","Isométrica","Passiva"],"explicacao":""},{"id":9292,"materia":"fisio","nivel":1,"enunciado":"A contração em que o músculo gera força sem mudar de comprimento é a:","opcoes":["Isométrica","Concêntrica","Excêntrica","Isocinética"],"explicacao":""},{"id":9293,"materia":"fisio","nivel":1,"enunciado":"Na escala de força muscular de 0 a 5, o grau 3 significa:","opcoes":["Movimento completo contra a gravidade, sem resistência","Ausência de contração","Força normal","Contração sem movimento"],"explicacao":""},{"id":9294,"materia":"fisio","nivel":1,"enunciado":"A escala de Berg avalia o:","opcoes":["Equilíbrio","Tônus","Nível de consciência","Risco de lesão por pressão"],"explicacao":""},{"id":9295,"materia":"fisio","nivel":2,"enunciado":"O teste de Phalen avalia a:","opcoes":["Síndrome do túnel do carpo","Lesão de menisco","Hérnia de disco","Epicondilite"],"explicacao":""},{"id":9296,"materia":"fisio","nivel":2,"enunciado":"O teste de Lasègue avalia:","opcoes":["Compressão de raiz nervosa lombar (ciatalgia)","Instabilidade do ombro","Lesão do joelho","Túnel do carpo"],"explicacao":""},{"id":9297,"materia":"fisio","nivel":2,"enunciado":"O teste de McMurray avalia lesão de:","opcoes":["Menisco","Ligamento cruzado posterior","Tendão patelar","Coluna cervical"],"explicacao":""},{"id":9298,"materia":"fisio","nivel":2,"enunciado":"O teste de Finkelstein avalia a:","opcoes":["Tenossinovite de De Quervain","Lesão do LCA","Fascite plantar","Hérnia de disco"],"explicacao":""},{"id":9299,"materia":"fisio","nivel":2,"enunciado":"O teste de Adams é usado para avaliar a:","opcoes":["Escoliose","Lesão de menisco","Artrose de quadril","Túnel do carpo"],"explicacao":""},{"id":9300,"materia":"fisio","nivel":2,"enunciado":"Na lesão do neurônio motor superior, observa-se:","opcoes":["Espasticidade, hiper-reflexia e sinal de Babinski","Flacidez e arreflexia","Fasciculações e atrofia precoce","Ausência total de tônus"],"explicacao":""},{"id":9301,"materia":"fisio","nivel":3,"en